/* snprintf(3) - Safe formatted string creation */
#include <stdio.h>
#include <stddef.h>
#include <stdlib.h>

#define BUF_SIZE 20

int main() {
    char buffer[BUF_SIZE];
    int count = 15;
    const char *user = "Administrator";
    const char *message = "Access granted";
    int ret;

    // Demonstrate a string that fits safely (ret < BUF_SIZE)
    ret = snprintf(buffer, BUF_SIZE, "%s: %s (Items: %d)", user, message, count);

    if (ret < 0) {
        fprintf(stderr, "snprintf failed during formatting.\n");
        return EXIT_FAILURE;
    }

    if ((size_t)ret < BUF_SIZE) {
        printf("Output success (Len: %d): %s\n", ret, buffer);
    } else {
        // This path is usually hit by truncation attempts
        printf("Output needed %d chars, but buffer is only %d.\n", ret, BUF_SIZE);
    }

    // Demonstrate truncation (output needed > BUF_SIZE)
    const char *long_user = "SuperUser_With_A_Very_Long_Name";
    ret = snprintf(buffer, BUF_SIZE, "%s: %s", long_user, message);

    if (ret >= BUF_SIZE) {
        printf("\nTruncation Warning: Required %d characters.\n", ret);
        printf("Truncated Result: %s\n", buffer);
    }

    return EXIT_SUCCESS;
}
